  ui_story_30900601_15_dialog_content = "Sí, pero solo hay un pequeño problema...",
  ui_story_30900601_16_dialog_content = "¡No hay nadie aquí!!!",
  ui_story_30900601_17_dialog_content = "Unas pocas personas se detuvieron a mirar, ¡pero nadie se quedó el tiempo suficiente para que terminara mi canción! ¡Ni siquiera puedo llegar al estribillo la mitad del tiempo!",
  ui_story_30900601_18_dialog_content = "¿Por qué mi amor y energía no les llega? ¿Hay algo mal conmigo?!",
  ui_story_30900601_19_dialog_content = "No me parece.",
  ui_story_30900601_20_dialog_content = "Incluso me cambié a este traje de baño para el espectáculo. ¡Todos deberían estar asombrados ahora mismo!",
  ui_story_30900601_21_dialog_content = "¿O es que mi traje de baño es realmente tan feo?!",
  ui_story_30900601_22_dialog_content = "...",
  ui_story_30900601_23_dialog_content = "¡Se ve bien, y es perfecto para ti!",
  ui_story_30900601_24_dialog_content = "¡Puedo decir ahora mismo que no se trata de ti!",
  ui_story_30900601_25_dialog_content = "¿De verdad lo crees? Ah, PlayerName, ¡sabía que lo entenderías!",
  ui_story_30900601_26_dialog_content = "Entonces, ¿qué podría ser...?",
  ui_story_30900601_27_dialog_content = "Estoy bastante seguro de que la gran reapertura del Hotel Tir' está pasando por algunos cambios en este momento.",
  ui_story_30900601_28_dialog_content = "Cuando llegué aquí por primera vez, había muchos más jóvenes de Umbraton y el desierto de Rediesel, pero ahora...",
