  ui_story_30900601_33_dialog_content = "Pueden verme bajo una luz equivocada ahora, pero una vez que termine mi espectáculo...",
  ui_story_30900601_34_dialog_content = "¡Estoy seguro de que todos se convertirán en mis fans!",
  ui_story_30900601_35_dialog_content = "Sí... También estoy seguro de ello!",
  ui_story_30900601_36_dialog_content = "Entonces, ¿algún consejo sobre lo que debería cambiar en mi rendimiento?",
