  ui_story_30900601_38_dialog_content = "Ya veo... ¿es por eso que me llamaste aquí hoy?",
  ui_story_30900601_39_dialog_content = "B-Bueno, no es como si estuviera admitiendo la derrota o algo así... ¡Pero simplemente no puedo pensar en ninguna buena idea en este momento!",
  ui_story_30900601_40_dialog_content = "¡Pero apuesto a que podrías crear algo increíble!",
  ui_story_30900601_41_dialog_content = "Mmm... sí sé un poco sobre sus gustos.",
  ui_story_30900601_42_dialog_content = "¡Aja, sabía que tenía razón al llamarte! Ahora, ¡enséñame la mejor manera de robar sus corazones!",
  ui_story_30900601_43_dialog_content = "Para empezar, tiene que haber una sensación de lujo.",
  ui_story_30900601_44_dialog_content = "Tome las palabras de este cartel, por ejemplo—",
  ui_story_30900601_45_dialog_content = "\"Reserva una habitación en el Hotel Tir' y recibe un boleto gratis para el concierto de Barbara.\"",
  ui_story_30900601_46_dialog_content = "Siempre que algo es gratis o fácil de conseguir, los ricos generalmente miran hacia otro lado.",
  ui_story_30900601_47_dialog_content = "¿Pero qué tal si lo cambiamos un poco? \"Reserva tu estancia en el ilustre Hotel Tir' para recibir asientos VIP para el exclusivo concierto de ídolos de Barbara.\"",
  ui_story_30900601_48_dialog_content = "¡Suena completamente diferente ahora!",
  ui_story_30900601_49_dialog_content = "¡Realmente tienes buen ojo para este tipo de cosas!",
  ui_story_30900601_50_dialog_content = "¡Si tan solo fueras mi agente...! Ahora, ¿qué más?!",
  ui_story_30900601_51_dialog_content = "Lo siguiente es una sensación de misterio.",
  ui_story_30900601_52_dialog_content = "Cuando las personas ricas no tienen nada mejor que hacer, asisten a conciertos. Han visto todo tipo de cosas allí.",
  ui_story_30900601_53_dialog_content = "¡Por eso necesitamos incluir algo que despierte su curiosidad! ¡Como un artista invitado secreto!",
  ui_story_30900601_54_dialog_content = "¡Ohhh! Un invitado secreto para actuar... ¡Eso es fácil! De hecho, ya tengo a alguien en mente.",
  ui_story_30900601_55_dialog_content = "¿Qué más, qué más?!",
  ui_story_30900601_56_dialog_content = "Por último, está el miedo a perderse algo.",
  ui_story_30900601_57_dialog_content = "Nadie está prestando mucha atención a tu concierto, por eso lo están ignorando...",
  ui_story_30900601_58_dialog_content = "Pero si escucharan a la gente en el Hotel Tir' diciendo cosas como—",
  ui_story_30900601_59_dialog_content = "\"¡De ninguna manera! ¿No me digas que aún no has visto la actuación de Barbara? ¡Tendrías que ser un tonto para perdértela!\"",
  ui_story_30900601_60_dialog_content = "¡Estas personas se apresurarán a ver tu espectáculo, ya que solo les importa mantenerse al día con otras personas ricas!",
  ui_story_30900601_61_dialog_content = "¡Eso es increíble... Y sin embargo, tiene mucho sentido!",
  ui_story_30900601_62_dialog_content = "No tenemos reglas sin sentido como esa en el Desierto de Rediesel. O te gusta algo o no te gusta, ¡así de simple!",
