  ui_story_30900601_76_dialog_content = "¡Estarás bien! Eres el invitado secreto, ¡y no sería tan sorprendente si estuvieras preparado!",
  ui_story_30900601_77_dialog_content = "Además, cuando la Rediesel Wrench y el último Celestita trabajan juntos...",
  ui_story_30900601_78_dialog_content = "¡No hay otro equipo como nosotros en el mundo! ¡Somos imparables!",
  ui_story_30900601_79_dialog_content = "De hecho, ¡esto incluso puede ser tu debut como el miembro más nuevo de mi nuevo grupo de música, las Dulzuras Celestitas!",
