  ui_story_30900601_82_dialog_content = "Y después, podríamos entrenar juntos y fortalecer aún más nuestro vínculo...",
  ui_story_30900601_83_option_content = "¡Quién sabe lo que podríamos lograr!",
  ui_story_30900601_84_dialog_content = "¡Estoy bastante seguro de que solo te estaría reteniendo!",
  ui_story_30900601_85_dialog_content = "Por el bien de tu sueño, creo que tendré que reconsiderarlo...",
