  ui_story_30900601_87_dialog_content = "¡Incluso yo tendría que planificar este tipo de cosas con cuidado, ya sabes!",
  ui_story_30900601_88_dialog_content = "¡De todos modos, cantemos esta canción con todo nuestro corazón!",
  ui_story_30900601_89_dialog_content = "¡¡¡Están todos listos!!!",
  ui_story_30900601_90_dialog_content = "Porque Barbara y PlayerName...",
