  ui_story_30900601_92_dialog_content = "¡Guauuuu!!!!",
  ui_story_30900601_93_dialog_content = "¡Es el Caelestite! ¡Es él! ¡Un Caelestite vivo y respirando!",
  ui_story_30900601_94_dialog_content = "¿Una oportunidad de escuchar cantar a la Caelestite? ¡Esto es increíble!",
